```js
function switchAdjectives(sentence) {
  // Split the string into an array of words, and filter out any stop words (like 'a', 'an', 'the')
  const words = sentence.split(" ")
    .filter(word => !["a", "an", "the"].includes(word.toLowerCase()))

  // Find the indices of the first and last adjectives
  let startIndex = 0;
  let endIndex = words.length - 1;
  while (!words[startIndex].endsWith('ly')) {
    startIndex++;
  }
  while (endIndex > 0 && !words[endIndex - 1].endsWith('ly')) {
    endIndex--;
  }

  // Swap the positions of the adjectives
  [words[startIndex], words[endIndex]] = [words[endIndex], words[startIndex]];

  // Join the words back into a sentence
  return words.join(" ");
