input_image = imread('image.jpg'); % Read input image
gray_image = rgb2gray(input_image); % Convert to grayscale

% Define Gaussian kernel
sigma = 1.5;
[gaussian_kernel, gaussian_stddev] = fspecial('gaussian', [5 5], sigma);

% Convolve input image with Gaussian kernel
filtered_image = filter(gaussian_kernel, gray_image, 'replicate');

% Define Sobel operators in x and y directions
sobel_x = [-1 0 1; -2 0 2; -1 0 1];
sobel_y = [-1 -2 -1; 0 0 0; 1 2 1];

% Apply Sobel operator to filtered image
edge_image_x = conv2(double(filtered_image), sobel_x, 'same');
edge_image_y = conv2(double(filtered_image), sobel_y, 'same');

% Combine edges in both directions and normalize
edge_image = sqrt(edge_image_x.^2 + edge_image_y.^2);
edge_image = double(edge_image)/max(max(edge_image));

% Display edge image
imshow(edge_image);
```

