CREATE DATABASE empowerid;
USE empowerid;
CREATE CONSTRAINT ON (account:Account) ASSERT account.AccountID IS UNIQUE;
CREATE CONSTRAINT ON (group:Group) ASSERT group.GroupID IS UNIQUE;
CREATE INDEX FOR (groupMember:GroupMemberGroup) ON (groupMember.MemberGroupID);
CREATE INDEX FOR (groupMember:GroupMemberGroup) ON (groupMember.GroupID);
