Here's a Swift function that identifies and corrects common homophone errors based on the rules defined in the prompt:

```swift
func correctHomophones(text: String) -> String {
    let homophones = ["there": "their", "they're"],
        contractions = ["no": "n't", "know": "knew", "sea": "see", "seems": "seem", "too": "to"]
    var result = ""

    for (key, value) in homophones {
        result = result.replacingOccurrences(of: key, with: value)
    }

    for (key, value) in contractions {
        result = result.replacingOccurrences(of: "\($key)\u{20}", with: "$value ")
        result = result.replacingOccurrences(of: " \($key)", with: " $value")
        result = result.replacingOccurrences(of: " \(key)", with: " $value")
    }

    return result
}

