function my_plugin_format_order( $order ) {
    // Get order date
    $date = date( 'd/m/Y', strtotime( $order->get_date_created() ) );

    // Get order number
    $order_number = $order->get_order_number();

    // Loop through order items to build formatted lines
    $lines = array();
    foreach ( $order->get_items() as $item ) {
        $tax_class = $item->get_tax_class();
        $price = $item->get_total();
        $qty = $item->get_quantity();

        // Add item line with price and quantity
        $line = "$date,$order_number,$item->get_product_id(),$item->get_name(),$price,$qty,0\n";

        // Add tax class lines if available
        if ( ! empty( $tax_class ) ) {
            $tax_rate = WC_Tax::calc_rate_for_item( $item );
            $taxable_amount = $item->get_subtotal() - $item->get_discount();
            $tax_amount = $taxable_amount * $tax_rate;
            $tax_line = "$date,$order_number,$item->get_product_id(),$tax_class,$taxable_amount,$tax_amount,-$tax_amount\n";
            $lines[] = $tax_line;
        }
    }

    // Add client total line
    $total = $order->get_total();
    $client_total = $total - $order->get_shipping_total() - $order->get_discount_total() - $order->get_taxes_total();
    $client_line = "$date,$order_number,,Client,$client_total,0,\n";
    $lines[] = $client_line;

    return implode( '', $lines );
}
