    name = models.CharField(max_length=255)
    value_a = models.FloatField()

class TableB(BaseTable):
    name = models.CharField(max_length=255)
    value_b = models.IntegerField()

class MyModel(models.Model):
    base_table = models.ForeignKey(BaseTable, null=True, blank=True, on_delete=models.SET_NULL)

    def __str__(self):
        if self.base_table is None:
            return ""
        elif isinstance(self.base_table, TableA):
            return f"{self.base_table.name} ({self.base_table.value_a})"
        else:
            return f"{self.base_table.name} ({self.base_table.value_b})"
```

