function getNestedValues(object, path) {
  let result = [];

  // Split the path into keys
  const keys = path.split('.');

  // Iterate through each key and traverse the object
  for (let I = 0; I < keys.length; i++) {
    const currentObject = object;

    // If we've reached the end of the path, add the value to the result array
    if (i === keys.length - 1) {
      result.push(currentObject[keys[i]]);

      // If the current object is an array, iterate through it and push matching values
    } else if (Array.isArray(currentObject[keys[i]])) {
      currentObject[keys[i]].forEach((val) => {
        getNestedValues(val, keys.slice(i + 1).join('.'));
      });

      // Continue traversing the object with the next key
    } else {
      currentObject = currentObject[keys[i]];
      getNestedValues(currentObject, keys.slice(i + 1).join('.'));
    }
  }

  // Return the result array
  return result;
}

