function getValuesFromObjectPath(object, path) {
  const keys = path.split('.');
  let currentObj = object;

  for (let I = 0; I < keys.length - 1; i++) {
    if (!currentObj[keys[i]]) {
      // If any intermediate key is not found, stop processing
      return [];
    }
    currentObj = currentObj[keys[i]];
  }

  const lastKey = keys[keys.length - 1];
  const values = [];

  if (typeof currentObj[lastKey] === 'object') {
    // If the final key points to an object, iterate over its properties
    Object.keys(currentObj[lastKey]).forEach(key => {
      values.push(currentObj[lastKey][key]);
    });
  } else {
    // Otherwise, add the single value
    values.push(currentObj[lastKey]);
  }

  return values;
}
```

The `getValuesFromObjectPath()` function takes two arguments: the object from which we want to extract values (`object`) and a string containing the path to the nested property or properties we're interested in (`path`). The path is specified using dot notation, with each segment representing a nested key.

The function returns an array containing all the values that match the final key in the path, or an empty array if the path leads to non-existent keys. Here's how you can use it:

