```python
class User:
    def __init__(self, productivity_level: float, work_style: str):
        self.productivity_level = productivity_level
        self.work_style = work_style

    @property
    def optimal_interval_length(self) -> int:
        return round(self.productivity_level * 25)

    @property
    def max_intervals_per_day(self) -> int:
        # Calculate max intervals based on productivity level and desired daily work time
        work_time = 60 * 25 * self.optimal_interval_length * 4
        max_intervals = int(work_time / (60 * 25))
        return min(max_intervals, 10)
```

