To ensure that the replacement of the specified word does not affect larger words that contain it, you can implement a suffix-prefix check while searching for the word to replace. This involves checking if the word being replaced has any characters before and after it that together form a valid English suffix or prefix. If so, then it's likely that the word is part of a larger word, and it should not be replaced.

Here's an example implementation:

```python
from re import search

def is_valid_suffix(word):
    # List of common English suffixes
    suffixes = ["able", "ible", "ly", "less", "ful", "ness"]

    # Check if any of the suffixes match the end of the word
    for suffix in suffixes:
        if search("$" + suffix + "$", word[-len(suffix):], flags=re.IGNORECASE):
            return True
    return False

def is_valid_prefix(word):
    # List of common English prefixes
    prefixes = {"un", "non", "im", "il", "dis", "re"}

    # Check if any of the prefixes match the beginning of the word
    for prefix in prefixes:
        if search("^" + prefix + "$", word[:len(prefix):], flags=re.IGNORECASE):
            return True
    return False

def replace_word(text, old_word, new_word):
    # Split text into list of words
    words = text.split()

    # Loop through each word in the list
    for i, word in enumerate(words):
        # Check if the current word contains the old word
        if old_word.lower() in word.lower():
            # Check if the old word is not part of a larger word (suffix or prefix)
            if not (is_valid_suffix(word) or is_valid_prefix(word)):
                # Replace the old word with the new word in this specific occurrence
                words[i] = words[i].replace(old_word, new_word)

    # Join the modified list of words back into a single string
    return " ".join(words)
``

