while true
    % Calculate number of offspring based on genotype
    numOffspringAA = genePool(:,1)*reproductionRateAA;
    numOffspringAB = genePool(:,2)*reproductionRateAB;
    numOffspringBB = (1-genePool(:,1))*(1-genePool(:,2))*reproductionRateBB;

    % Update gene pool with new offspring
    newGenePool = [numOffspringAA numOffspringAB; numOffspringAA numOffspringBB];

    % Calculate new gene pool survival rates
    newSurvivalRateA = sum(newGenePool(:,1))/sum(newGenePool);
    newSurvivalRateB = sum(newGenePool(:,2))/sum(newGenePool);

    % Update gene pool with surviving individuals
    genePool = newGenePool(randi([0 size(newGenePool),1],1),[newSurvivalRateA newSurvivalRateB]);

    % Display results after each generation
