```hcl
resource "local_file" "ps_script" {
  content = templatefile("${path.module}/ps_script.ps1", {
    user_input = var.user_input
  })
}

data "external" "powershell_output" {
  program = ["powershell", "-ExecutionPolicy", "Bypass", "-Command", "${local_file.ps_script.filename}", "-ArgumentList", "$(Get-Content ${local_file.ps_script.filename}.args)", "(Get-Content ${local_file.ps_script.filename}.args)"]
  query = {
