```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';
import { ExecutionContext } from '@nestjs/core';
import { Observable } from 'rxjs';

@Injectable()
export class DevelopmentOnlyMiddleware implements NestMiddleware {
  public use(handler: Function): Function {
    return function (...args: any[]): Observable<any> | Promise<any> | any {
      const ctx = args[0] as ExecutionContext;
      const req = ctx.switchToHttp().getRequest();

      // Check if we're running in development mode
      if (req.app.get('env') !== 'development') {
        return handler.apply(this, args);
      }

      // Return false to prevent further execution in production
      return Observable.create(() => {});
    };
  }
}
```

To use this decorator, simply apply it to your controller methods or classes that you want to restrict to development mode only:

```typescript
import { Controller, Get } from '@nestjs/common';
import { DevelopmentOnlyMiddleware } from './middleware/development-only.middleware';

@Controller()
class MyController {
  @Get()
  @DevelopmentOnlyMiddleware()
  get(): string {
    return 'Hello World!';
  }
}
```

This middleware checks the `NODE_ENV` variable by accessing the Nest application instance from the request context. If the environment is not 'development', then the handler function is executed normally. Otherwise, an empty observable is returned to prevent further execution and return a false value instead. This can be customized based on your specific requirements.

Here's an implementation of the requested decorator using NestJS:

```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';
import { ExecutionContext } from '@nestjs/core';
import { Observable } from 'rxjs';

@Injectable()
export class EnvironmentGuard implements NestMiddleware {
  use(context: ExecutionContext): Observable<void> | Promise<void> | void {
    const req = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'production') {
      return super.use.call(this, context); // Call original middleware
    }

    console.log('Environment is not production');
    return false; // Return false to prevent further execution
  }
}
```

To use this decorator, simply apply it to your controller or endpoint methods:

```typescript
import { Body, Controller, Post, UseGuards } from '@nestjs/common';
import { ApiOperation } from '@nestjs/swagger';
import { CreateUserDto } from './dto/create-user.dto';
import { AuthGuard } from '../auth/auth.guard';
import { EnvironmentGuard } from '../environment/environment.guard';

@Controller('users')
export class UsersController {
  @UseGuards(AuthGuard)
  @Post()
  @ApiOperation({ summary: 'Create user' })
  create(@Body() dto: CreateUserDto) {
    // Your code here
  }

  @UseGuards(EnvironmentGuard)
  @Post('/admin')
  @ApiOperation({ summary: 'Admin only feature' })
  adminOnly(@Body() dto: CreateUserDto) {
    // Your code here
  }
}
```

In this example, `EnvironmentGuard` checks whether the current environment is production or not, and allows the request to proceed to the next middleware (or endpoint) if it is, or returns `false` immediately otherwise. You can replace `console.log()` with whatever logic you want in that case.

Here's the implementation of the requested decorator:

```typescript
import { Injectable } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { NestMiddleware, NestMiddlewareFunction } from './decorators';
import { Logger } from './logger.service';

@Injectable()
export class EnvGuard implements NestMiddleware {
  constructor(private logger: Logger) {}

  execute(next: Function): NestMiddlewareFunction {
    return (req, res, ctx) => {
      const nodeEnv = process.env.NODE_ENV;
      if (nodeEnv === 'production') {
        return next();
      } else {
        this.logger.warn('Running in development mode');
        return false;
      }
    };
  }
}

function envGuard(): ClassDecorator & MethodDecorator {
  return function(target: Object | Function, propertyKey?: string | symbol): void {
    Reflect.defineMetadata('env-guard', new EnvGuard(), target);
    if (typeof target === 'function') {
      Reflect.defineMetadata('env-guard', new EnvGuard(), target);
    }
  };
}

export const useEnvGuard = () => {
  NestFactory.createMicroservice(); // Use in microservices
};

export const useEnvGuardMiddleware = () => {
  return [new EnvGuard()]; // Use in applications
};

