const scriptUrl = 'path/to/your/script.js';

function executeScript(tabId) {
  chrome.scripting.executeScript({
    code: '', // An empty code is required to inject a local file
    file: scriptUrl,
    matchTabs: [tabId],
    runAt: 'document_start',
  });
}

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  // Check if the updated tab matches our criteria for injection
  const urlRegex = /^https:\/\/example\.com$/;
  const url = new URL(tab.url);
  const isMatch = urlRegex.test(url.origin) && changeInfo.status === 'complete';
  if (isMatch) {
    executeScript(tabId);
  }
});

tabs.getActive().then((activeTab) => {
  // Automatically inject script on startup
  executeScript(activeTab.id);
});
```

