my_filter <- function(data, ...) {
  vars <- extract_vars(list(...))
  values <- extract_values(list(...))
  filtered_data <- data %>%
    select(everything(), ! vars) %>%
    mutate_at(vars, funs(eval(parse(text = .)))) %>%
    filter(funs(eval(parse(text = .)))) %>%
    select(-(names(data)[match(vars, names(data)):match(names(data)[length(names(data)):-1], names(data)))]))
  return(filtered_data)
}

# Extract variables and their corresponding values from arguments passed to filter()
extract_vars <- function(args) {
  vars <- character(0)
  for (i in seq_along(args)) {
    if (is.character(args[[i]])) {
      vars <- c(vars, args[[i]])
    }
  }
  return(unique(sort(union(setdiff(names(args), vars), vars)))[!duplicated(union(setdiff(names(args), vars), vars)))]))
}

