```swift
func isOlderThanThreeYears(_ url: URL) -> Bool {
    let fileCoordinator = NSFileCoordinator()
    var dateOfLastUse: Date?

    do {
        try fileCoordinator.coordinate(readingItemAt: url, options: []) { itemURL in
            dateOfLastUse = FileManager.default.attributes(ofItemAtPath: itemURL.path)[.lastUsedDate] as? Date
        }
    } catch {}

    return Calendar.current.startOfDay(for: Date().addingTimeIntervals(-1095))?.timeIntervalSince(dateOfLastUse ?? Date()) ?? Double.infinity > 0
}
```

This function takes a `URL` representing the location of the file and returns a Boolean indicating whether it's older than three years based on its last usage date. The function uses `NSFileCoordinator` to ensure that other processes don't modify the file while we're reading its attributes.

