function CheckSIDHistory($sid) {
    $sidObject = New-Object System.Security.Principal.WindowsPrincipal(null)
    $sidPrincipal = $sidObject.CreatePrincipalSource($sid)
    $sidAccount = [System.Runtime.Interopservices.Marshal]::SecureStringToBSTR([Runtime.Interopservices.Marshal]::StringToHGlobalAuto(0))
