        $sidHistory = [ADSI]("WinNT://$domainName/Users('$sidAccountPtr')")
        $sidHistory.Filter = "objectCategory=person;objectClass=userAccountControl"
        $sidHistory.PropertiesToLoad.Add("sidhistory")
        $sidHistory.Search()
        return ($sidHistory.Properties["sidhistory"][0].Value -ne "")
    } finally {
        [System.Runtime.Interopservices.Marshal]::FreeCoTaskMem($sidAccountPtr)
    }
}

